<?php declare(strict_types=1);require_once __DIR__.'/bootstrap.php';function portal_client_id():int{return (int)portal_require_user()['client_id'];}function portal_project(int $id):array{$q=$GLOBALS['db']->prepare('SELECT * FROM client_projects WHERE id=? AND client_id=? LIMIT 1');$q->execute([$id,portal_client_id()]);$r=$q->fetch();if(!$r){http_response_code(404);exit('Project not found.');}return $r;}function portal_ticket(int $id):array{$q=$GLOBALS['db']->prepare('SELECT * FROM support_tickets WHERE id=? AND client_id=? LIMIT 1');$q->execute([$id,portal_client_id()]);$r=$q->fetch();if(!$r){http_response_code(404);exit('Ticket not found.');}return $r;}function portal_approval(int $id):array{$q=$GLOBALS['db']->prepare('SELECT * FROM project_approvals a JOIN client_projects p ON p.id=a.project_id WHERE a.id=? AND p.client_id=? LIMIT 1');$q->execute([$id,portal_client_id()]);$r=$q->fetch();if(!$r){http_response_code(404);exit('Approval not found.');}return $r;}